/**
 * GPU-accelerated stable radix sort using the Blelloch scan algorithm.
 *
 * ComputeRadixSort provides an O(n) stable sorting algorithm that runs entirely on the GPU.
 * It uses a configurable radix (1, 2, or 4 bits per pass) with workgroup-local prefix sums
 * for optimal performance.
 *
 * ## Algorithm
 *
 * For each N-bit pass:
 * 1. **Phase 1 - Local Histogram + Prefix Sum**: Each workgroup counts digit occurrences
 *    and computes local prefix sums using shared memory
 * 2. **Phase 2 - Global Prefix Sum**: Compute prefix sum on workgroup totals
 * 3. **Phase 3 - Scatter**: Write elements to sorted positions using deterministic offsets
 *
 * ## Radix Bits Configuration
 *
 * | Bits | Buckets | Passes | Memory | Best For |
 * |------|---------|--------|--------|----------|
 * | 1    | 2       | 32     | Lowest | Small datasets, low memory |
 * | 2    | 4       | 16     | Low    | General use (default) |
 * | 4    | 16      | 8      | Medium | Large datasets, fewer passes |
 *
 * ## Stability
 *
 * The algorithm is inherently stable because:
 * - Local prefix sums preserve element order within each workgroup
 * - Global prefix sums preserve workgroup order
 * - No atomic operations in scatter phase (deterministic positions)
 *
 * ## Usage
 *
 * ```javascript
 * import { instancedArray } from 'three/tsl';
 * import { ComputeRadixSort } from '@three-blocks/core';
 *
 * // Create a buffer of uint keys to sort
 * const keysBuffer = instancedArray(new Uint32Array([5, 2, 8, 1, 9, 3]), 'uint');
 *
 * // Optional: values buffer to sort alongside keys
 * const valuesBuffer = instancedArray(new Uint32Array([50, 20, 80, 10, 90, 30]), 'uint');
 *
 * // Initialize the sorter (default 2-bit radix)
 * const sorter = new ComputeRadixSort(keysBuffer, { values: valuesBuffer });
 *
 * // Or use 4-bit radix for fewer passes on large datasets
 * const fastSorter = new ComputeRadixSort(keysBuffer, { radixBits: 4 });
 *
 * // In your render loop:
 * sorter.compute(renderer);
 * // Result: keys = [1, 2, 3, 5, 8, 9], values = [10, 20, 30, 50, 80, 90]
 * ```
 *
 * @class ComputeRadixSort
 * @short Stable GPU radix sort; O(n) complexity, eliminates flickering in Gaussian Splatting
 * @category Compute
 * @tags WebGPU
 */
export class ComputeRadixSort {
    /**
     * Creates a new GPU radix sorter.
     *
     * @param {StorageBufferNode} keysBuffer - The storage buffer containing uint32 keys to sort.
     * @param {Object} [options={}] - Configuration options.
     * @param {StorageBufferNode} [options.values] - Optional buffer of values to sort alongside keys.
     * @param {number} [options.workgroupSize=256] - The workgroup size for compute shaders.
     * @param {number} [options.radixBits=2] - Bits per sorting pass (1, 2, or 4). Higher values mean fewer passes but more memory.
     * @param {number} [options.keyBits=32] - Effective key width in bits (16 or 32). Use 16 for faster sorting with reduced precision.
     */
    constructor(keysBuffer: StorageBufferNode, options?: {
        values?: StorageBufferNode;
        workgroupSize?: number;
        radixBits?: number;
        keyBits?: number;
    });
    /**
     * The storage buffer containing keys to sort.
     * @type {StorageBufferNode}
     */
    keysBuffer: StorageBufferNode;
    /**
     * Optional values buffer to sort alongside keys.
     * @type {StorageBufferNode|null}
     */
    valuesBuffer: StorageBufferNode | null;
    /**
     * Number of elements to sort.
     * @type {number}
     */
    count: number;
    /**
     * Number of radix bits per pass (1, 2, or 4).
     * @type {number}
     */
    radixBits: number;
    /**
     * Effective key width in bits (16 or 32).
     * Use 16 for faster sorting with reduced precision (halves number of passes).
     * @type {number}
     */
    keyBits: number;
    /**
     * Number of buckets (2^radixBits).
     * @type {number}
     */
    bucketCount: number;
    /**
     * Bit mask for extracting digits (bucketCount - 1).
     * @type {number}
     */
    bitMask: number;
    /**
     * Number of passes (keyBits / radixBits).
     * With keyBits=16 and radixBits=2, this is 8 passes instead of 16.
     * @type {number}
     */
    passCount: number;
    /**
     * Threads per workgroup.
     * @type {number}
     */
    workgroupSize: number;
    /**
     * Elements processed per workgroup (2 per thread).
     * @type {number}
     */
    elementsPerWorkgroup: number;
    /**
     * Number of workgroups.
     * @type {number}
     */
    workgroupCount: number;
    /**
     * Uniform for current bit offset.
     * @type {UniformNode}
     */
    bitOffsetUniform: UniformNode;
    /**
     * Whether initialized.
     * @type {boolean}
     */
    initialized: boolean;
    /**
     * Current read buffer name ('Keys' or 'Temp').
     * @type {string}
     */
    readBufferName: string;
    /**
     * Allocates GPU buffers for the radix sort algorithm.
     *
     * Buffer count is kept minimal to stay within WebGPU limits (typically 8 storage buffers per bind group).
     * Total buffers: keysBuffer, tempKeysBuffer, [valuesBuffer, tempValuesBuffer], localPrefixBuffer,
     * digitCountsBuffer, digitTotalsBuffer = 5-7 buffers.
     *
     * @private
     */
    private _allocateBuffers;
    /**
     * Temporary keys buffer for ping-pong.
     * @type {StorageBufferNode}
     */
    tempKeysBuffer: StorageBufferNode;
    /**
     * Temporary values buffer for ping-pong.
     * @type {StorageBufferNode|null}
     */
    tempValuesBuffer: StorageBufferNode | null;
    /**
     * Per-element local prefix sums (one uint per bucket per element).
     * Layout: element[i] bucket[d] -> index i * bucketCount + d
     * @type {StorageBufferNode}
     */
    localPrefixBuffer: StorageBufferNode;
    /**
     * Consolidated per-workgroup digit counts for all buckets.
     * Layout: digit[d] workgroup[wg] -> index d * workgroupCount + wg
     * After prefix sum phase, contains cumulative counts.
     * @type {StorageBufferNode}
     */
    digitCountsBuffer: StorageBufferNode;
    /**
     * Global digit totals and base positions (bucketCount * 2 elements).
     * First half [0..bucketCount-1]: total count for each digit
     * Second half [bucketCount..2*bucketCount-1]: base position for each digit
     * @type {StorageBufferNode}
     */
    digitTotalsBuffer: StorageBufferNode;
    /**
     * Initializes the sorter for the given renderer.
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     */
    init(renderer: WebGPURenderer): void;
    /**
     * Builds all compute shaders for the radix sort algorithm.
     * @private
     */
    private _buildComputeShaders;
    _phase1Fns: {
        Keys: any;
        Temp: any;
    };
    _computeTotalsFn: any;
    _phase3Fns: {
        Keys: any;
        Temp: any;
    };
    _alignFn: any;
    /**
     * Builds Phase 1: Local histogram + prefix sum kernel.
     *
     * This kernel:
     * 1. Loads elements and categorizes by N-bit digit
     * 2. Uses bucketCount workgroup arrays to mark which digit each element has
     * 3. Runs Blelloch scan on all arrays to compute local prefix sums
     * 4. Outputs per-element local offsets and per-workgroup bucket totals
     *
     * @private
     */
    private _buildPhase1;
    /**
     * Builds kernel to compute global digit totals, base positions, and prefix sums.
     *
     * This kernel runs on a single thread and:
     * 1. Computes total count for each digit
     * 2. Computes base positions (cumulative totals across digits)
     * 3. Computes exclusive prefix sum for each digit's workgroup counts
     *
     * @private
     */
    private _buildComputeTotals;
    /**
     * Builds Phase 3: Scatter/reorder kernel.
     *
     * This kernel:
     * 1. Reads each element's key and determines its digit
     * 2. Computes destination: globalBase + prefixSum[digit][workgroup] + localPrefix
     * 3. Writes the element to its final sorted position
     *
     * @private
     */
    private _buildPhase3;
    /**
     * Builds align kernel to copy temp back to keys if needed.
     * @private
     */
    private _buildAlign;
    /**
     * Executes a single sorting pass.
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     * @param {number} bitOffset - The bit offset for this pass.
     */
    computePass(renderer: WebGPURenderer, bitOffset: number): void;
    /**
     * Executes a complete radix sort (all passes).
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     */
    compute(renderer: WebGPURenderer): void;
    /**
     * Executes a single step of the radix sort (one pass).
     *
     * Call this method `passCount` times to complete a full 32-bit sort.
     * Useful for amortizing sort cost across multiple frames.
     *
     * @param {WebGPURenderer} renderer - The Three.js WebGPU renderer.
     * @param {number} passIndex - Pass index (0 to passCount-1).
     */
    computeStep(renderer: WebGPURenderer, passIndex: number): void;
    /**
     * Disposes of GPU resources held by this sorter.
     */
    dispose(): void;
}
